package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsNpcSetup {
 static CityNpcSetup.Check check(CityNpcSetup.Inspection r,String key){return r.checks().stream().filter(c->c.key().equals(key)).findFirst().orElseThrow();}
 @GameTest(template="empty") public static void repeatedReadinessChecksNeverFundEnableOrChangeWorldState(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);d.state.enabled.remove(f.city.id);f.city.works.enabled=false;var link=f.box();var box=d.state.boxes.get(RuralSettlement.key(f.city.id,f.chest.asLong()));box.stock.wheat=4;String rural=CityEconomy.JSON.toJson(d.state),economy=CityEconomy.JSON.toJson(CityEconomy.get(f.server).state),trade=CityEconomy.JSON.toJson(CityTrade.get(f.server).state),city=CityEconomy.JSON.toJson(f.city.housing);var template=CityNpcDesigner.defaults(f.person.role);for(int n=0;n<10;n++)CityNpcSetup.inspect(f.server,f.city,f.worker,template);h.assertTrue(rural.equals(CityEconomy.JSON.toJson(d.state))&&economy.equals(CityEconomy.JSON.toJson(CityEconomy.get(f.server).state))&&trade.equals(CityEconomy.JSON.toJson(CityTrade.get(f.server).state))&&city.equals(CityEconomy.JSON.toJson(f.city.housing)),"Repeated diagnostics do not create policies, accounts, grants, stock, housing or startup side effects");}h.succeed();}
 @GameTest(template="empty") public static void housingUsesActualFamilyHomeAndDestroyedHomesAreMissing(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var family=RuralSettlement.get(f.server).state.families.get(f.person.family);f.house.beds=3;f.house.residents.add(f.worker);var t=CityNpcDesigner.defaults(f.person.role);h.assertTrue(FamilyLivelihood.home(f.city,family)&&check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"home").level()==3,"Use the existing family housing rule");f.house.damaged.addAll(f.house.baseline.keySet());h.assertTrue(!FamilyLivelihood.home(f.city,family)&&check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"home").level()==1,"A fully destroyed home must not appear ready");}h.succeed();}
 @GameTest(template="empty") public static void foodChecksSeparateMissingBoxEmptyBoxAndActualFamilyStock(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var t=CityNpcDesigner.defaults(f.person.role);h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"store").level()==1,"No ordinary box substitutes for registered NPC storage");f.box();var d=RuralSettlement.get(f.server);var box=d.state.boxes.get(RuralSettlement.key(f.city.id,f.chest.asLong()));box.linked=true;box.stock.family=f.person.family;h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"store").level()==2,"Empty associated box is a food warning, not a missing box");box.stock.wheat=3;h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"store").level()==3,"Real stored food clears the stock warning without filling the box");box.stock.family=UUID.randomUUID();h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"store").level()==1,"Another family's food is not counted");}h.succeed();}
 @GameTest(template="empty") public static void familyLiquidityIncludesOtherMembersWithoutDuplicatingMoney(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var family=d.state.families.get(f.person.family);var partner=new RuralRules.Person();partner.id=UUID.randomUUID();partner.family=family.id;partner.name="家人";d.state.people.put(partner.id,partner);family.members.add(partner.id);f.city.residents.add(partner.id);var e=CityEconomy.get(f.server);e.state.accounts.put(CityEconomy.person(f.worker),0L);e.state.accounts.put(CityEconomy.person(partner.id),17L);long total=f.money();var result=CityNpcSetup.inspect(f.server,f.city,f.worker,CityNpcDesigner.defaults(f.person.role));h.assertTrue(result.familyCash()==17&&check(result,"cash").level()==3&&f.money()==total,"Personal zero does not falsely mark a funded family as broke; reading never transfers money");}h.succeed();}
 @GameTest(template="empty") public static void businessInventoryPreventsFalseBankruptcyWarning(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var trade=CityTrade.get(f.server);var b=new CityTrade.Business();b.id=UUID.randomUUID();b.city=f.city.id;b.worker=f.worker;b.account="trade:"+b.id;b.kind="baker";trade.state.businesses.put(b.id,b);try{var t=CityNpcDesigner.defaults(RuralRules.Role.BAKER);h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"cash").level()==1,"Zero cash and no stock is a missing-cash warning");b.cargo[0].add(2,200);var report=CityNpcSetup.inspect(f.server,f.city,f.worker,t);h.assertTrue(check(report,"cash").level()==2&&check(report,"cash").detail().contains("零现金不等于没有资产")&&!CityEconomy.get(f.server).state.accounts.containsKey(b.account),"In-transit stock is recognized and a missing account is not silently opened or funded");}finally{trade.state.businesses.remove(b.id);}}h.succeed();}
 @GameTest(template="empty") public static void maintenanceSwitchDoesNotMasqueradeAsResidentSimulation(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var t=CityNpcDesigner.defaults(f.person.role);d.state.enabled.remove(f.city.id);f.city.works.enabled=true;h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"run").level()==1,"Maintenance alone does not start residents");d.state.enabled.add(f.city.id);f.city.works.enabled=false;h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"run").level()==2,"Resident loop and paused maintenance appear separately");f.city.works.enabled=true;h.assertTrue(check(CityNpcSetup.inspect(f.server,f.city,f.worker,t),"run").level()==3,"Both existing flags must be on for the fully-running summary");}h.succeed();}
 @GameTest(template="empty") public static void storageShortcutUsesExistingBindingAndConservesGoods(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);var link=f.box();var box=d.state.boxes.get(RuralSettlement.key(f.city.id,f.chest.asLong()));box.linked=false;box.stock.family=null;link.offset=null;var p=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),new com.mojang.authlib.GameProfile(f.city.owner,"setup-owner"));p.setGameMode(GameType.CREATIVE);p.setPos(f.chest.getX(),f.chest.getY(),f.chest.getZ());long money=f.money();CityNpcSetup.bind(p,f.city,f.worker,f.chest.asLong());h.assertTrue(box.linked&&f.person.family.equals(box.stock.family)&&link.offset.equals(f.bench.subtract(f.chest))&&box.stock.free()==10&&f.money()==money,"Shortcut delegates existing storage-wand binding; no goods or money are generated");var other=UUID.randomUUID();box.stock.family=other;h.assertTrue(!CityNpcSetup.canBind(f.server,f.city,f.worker,box)&&other.equals(box.stock.family),"Do not reassign another family's box in the shortcut");RuralTools.selected.remove(p.getUUID());RuralTools.selectedSite.remove(p.getUUID());}h.succeed();}
 @GameTest(template="empty") public static void uncreatedNpcAndMissingCityStayExplicitWithoutEnrollment(GameTestHelper h){try(var f=new CityTestsCityWorks.Fixture(h)){var d=RuralSettlement.get(f.server);int people=d.state.people.size();long money=f.money();var unknown=UUID.randomUUID();var t=CityNpcDesigner.defaults(RuralRules.Role.FARMER);var noCity=CityNpcSetup.inspect(f.server,null,unknown,t);var notCreated=CityNpcSetup.inspect(f.server,f.city,unknown,t);h.assertTrue(noCity.checks().stream().allMatch(c->c.level()==0)&&check(notCreated,"home").level()==0&&check(notCreated,"store").level()==0&&check(notCreated,"cash").level()==0&&d.state.people.size()==people&&f.money()==money,"Planning-stage hints never create a person, family, account, house or cash");}h.succeed();}
}
